  function lang(){var s=document.getElementById('lang-select'),v=s&&s.value;if(!v){try{v=localStorage.getItem('dx-lang')||localStorage.getItem('dx-pwa-lang');}catch(_){}}v=String(v||document.documentElement.lang||navigator.language||'fr').slice(0,2).toLowerCase();return TEXT[v]?v:'fr';}
  function tr(key,vars){var value=(TEXT[lang()]&&TEXT[lang()][key])||TEXT.fr[key]||key;Object.keys(vars||{}).forEach(function(name){value=value.split('{'+name+'}').join(String(vars[name]));});return value;}
  function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
  function finite(v){var n=Number(v);return Number.isFinite(n)?n:null;}
  function fmtBytes(bytes){var n=Math.max(0,Number(bytes)||0),u=['B','KB','MB','GB','TB'],i=0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return(i?n.toFixed(n>=10?1:2):Math.round(n))+' '+u[i];}
  function fmtPct(v){var n=finite(v);return n===null?'—':Math.round(n)+' %';}
  function fmtDate(v){var n=Number(v)||Date.parse(v||'');if(!n)return tr('notAvailable');try{return new Date(n).toLocaleString();}catch(_){return tr('notAvailable');}}
  function fmtDuration(seconds){var s=Math.max(0,Math.round(Number(seconds)||0)),d=Math.floor(s/86400);s%=86400;var h=Math.floor(s/3600);s%=3600;var m=Math.floor(s/60);if(d)return d+' d '+h+' h';if(h)return h+' h '+m+' min';return m+' min';}
  function hasAdminAccess(session){return !!(session&&session.authenticated&&(session.role==='owner'||session.role==='admin'));}
  function setAdminAccess(session){var previous=adminAccess;adminAccess=hasAdminAccess(session);var c=document.getElementById('dx-admin-advanced-card');if(c)c.hidden=!adminAccess;if(!adminAccess){requestSeq++;historySeq++;diagnosticSeq++;tlsFixSeq++;caSeq++;emergencySeq++;refreshPromise=null;clearSensitive();}if(document.body)document.body.setAttribute('data-pwa-admin-access',adminAccess?'1':'0');if(previous!==adminAccess||!accessAnnounced){accessAnnounced=true;try{document.dispatchEvent(new CustomEvent('dx-pwa-admin-access',{detail:{enabled:adminAccess}}));}catch(_){}}return adminAccess;}
