  function ensureStandardHealthAssets(){
    if(window.DirectXferServerHealth)return Promise.resolve(window.DirectXferServerHealth);
    if(standardHealthAssetsPromise)return standardHealthAssetsPromise;
    standardHealthAssetsPromise=new Promise(function(resolve,reject){
      var existing=document.getElementById('dx-server-health-standard-js');
      if(existing){existing.addEventListener('load',function(){resolve(window.DirectXferServerHealth||null);},{once:true});existing.addEventListener('error',reject,{once:true});return;}
      var script=document.createElement('script');script.id='dx-server-health-standard-js';script.src='/server-health-dashboard.js?v=469';script.defer=false;script.onload=function(){resolve(window.DirectXferServerHealth||null);};script.onerror=function(){standardHealthAssetsPromise=null;reject(new Error('server-health-assets'));};document.head.appendChild(script);
    });
    return standardHealthAssetsPromise;
  }

