  function refresh(force){
    if(!adminAccess)return Promise.resolve();
    if(!force&&!panelVisible())return Promise.resolve();
    return ensureStandardHealthAssets().then(function(api){if(!api)return;if(panelVisible()&&typeof api.start==='function')api.start();else if(force&&typeof api.refresh==='function')return api.refresh(true);});
  }
  async function syncAdminAccess(force){
    try{
      var session=await ensureSession(!!force);
      if(!setAdminAccess(session)){if(window.DirectXferServerHealth&&typeof window.DirectXferServerHealth.stop==='function')window.DirectXferServerHealth.stop();return false;}
      clearTimeout(accessRetryTimer);
      await ensureStandardHealthAssets();
      if(panelVisible()&&window.DirectXferServerHealth&&typeof window.DirectXferServerHealth.start==='function')window.DirectXferServerHealth.start();
      return true;
    }catch(e){
      resetSessionCache();
      // Only an authoritative auth failure should revoke an already confirmed admin UI.
      if(e&&(e.status===401||e.status===403))setAdminAccess(null);
      else { clearTimeout(accessRetryTimer); accessRetryTimer=setTimeout(function(){syncAdminAccess(true);},1500); }
      return false;
    }
  }
  function syncBuildTag(){var t=document.getElementById('build-tag');if(t)t.textContent='v'+RELEASE+' · '+BUILD.replace(/^.*-/,'');}
  function startRefreshLoop(){
    clearInterval(refreshTimer);
    refreshTimer=setInterval(function(){
      syncAdminAccess(false).catch(function(){});
      if(panelVisible()&&window.DirectXferServerHealth&&typeof window.DirectXferServerHealth.refresh==='function')window.DirectXferServerHealth.refresh(false);
    },15000);
  }
  function init(){
    addStyles();var card=makeCard();syncBuildTag();startRefreshLoop();syncAdminAccess(true);
    if(window.MutationObserver)new MutationObserver(function(){
      syncBuildTag();syncAdminAccess(false);
      if(document.body.getAttribute('data-pwa-active-panel')==='system-health')ensureStandardHealthAssets().then(function(api){if(adminAccess&&api&&typeof api.start==='function')api.start();}).catch(function(){});
      else if(window.DirectXferServerHealth&&typeof window.DirectXferServerHealth.stop==='function')window.DirectXferServerHealth.stop();
    }).observe(document.body,{attributes:true,attributeFilter:['data-pwa-active-panel']});
    document.addEventListener('visibilitychange',function(){if(!document.hidden)syncAdminAccess(true);});
    window.addEventListener('pageshow',function(){syncAdminAccess(true);});
    window.addEventListener('online',function(){syncAdminAccess(true);});
    window.addEventListener('focus',function(){syncAdminAccess(false);});
    window.addEventListener('pagehide',function(){clearInterval(refreshTimer);clearTimeout(accessRetryTimer);requestSeq++;historySeq++;diagnosticSeq++;tlsFixSeq++;caSeq++;emergencySeq++;resetSessionCache();if(window.DirectXferServerHealth&&typeof window.DirectXferServerHealth.stop==='function')window.DirectXferServerHealth.stop();});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
